import tkinter as tkimport shutil"""Faire un exe:pip install pyinstallerpyinstaller --onefile --noconsole monitor_disk.py=> dist/monitor_disk.exe (9Mo)Pour tuer le programme:taskkill /F /IM monitor_disk.exe"""# =========================================================# CONFIGURATION# =========================================================REFRESH_MS = 5000RIGHT_MARGIN = 270TOP_MARGIN = -2# =========================================================# ESPACE DISQUE# =========================================================def get_free_space(drive):    try:        free = shutil.disk_usage(drive).free        return free / (1024 ** 3)    except Exception:        return None# =========================================================# MISE À JOUR# =========================================================after_id = Nonedef update():    global after_id    c = get_free_space("C:\\")    d = get_free_space("D:\\")    parts = []    if c is not None:        parts.append(f"C: {c:.1f} Go")    else:        parts.append("C: ?")    if d is not None:        parts.append(f"D: {d:.1f} Go")    else:        parts.append("D: ?")    label.config(        text="    ".join(parts)    )    # Mémorise l'identifiant du timer    after_id = root.after(        REFRESH_MS,        update    )# =========================================================# FERMETURE PROPRE# =========================================================def exit_app():    global after_id    # Annule le prochain appel de update()    if after_id is not None:        try:            root.after_cancel(after_id)        except tk.TclError:            pass        after_id = None    # Ferme la fenêtre    root.destroy()# =========================================================# DÉPLACEMENT DE LA FENÊTRE# =========================================================drag_x = 0drag_y = 0def start_move(event):    global drag_x, drag_y    drag_x = event.x    drag_y = event.ydef move_window(event):    x = (        root.winfo_x()        + event.x        - drag_x    )    y = (        root.winfo_y()        + event.y        - drag_y    )    root.geometry(        f"+{x}+{y}"    )# =========================================================# FENÊTRE# =========================================================root = tk.Tk()# Pas de bordure / barre de titreroot.overrideredirect(True)# Toujours au-dessusroot.attributes(    "-topmost",    True)# Transparence 80 %root.attributes(    "-alpha",    0.80)root.configure(    bg="black")# =========================================================# MENU CONTEXTUEL# =========================================================context_menu = tk.Menu(    root,    tearoff=False)context_menu.add_command(    label="Exit",    command=exit_app)def show_context_menu(event):    context_menu.post(        event.x_root,        event.y_root    )# =========================================================# LABEL# =========================================================label = tk.Label(    root,    text="",    font=("Segoe UI", 8),    fg="white",    bg="gray",    padx=2,    pady=0)label.pack()# =========================================================# CLIC GAUCHE = DÉPLACEMENT# =========================================================root.bind(    "<Button-1>",    start_move)root.bind(    "<B1-Motion>",    move_window)label.bind(    "<Button-1>",    start_move)label.bind(    "<B1-Motion>",    move_window)# =========================================================# CLIC DROIT = MENU# =========================================================root.bind(    "<Button-3>",    show_context_menu)label.bind(    "<Button-3>",    show_context_menu)# =========================================================# FORCE LE CALCUL DE LA TAILLE# =========================================================root.update_idletasks()# =========================================================# POSITION INITIALE HAUT-DROITE# =========================================================screen_width = root.winfo_screenwidth()window_width = root.winfo_width()x = (    screen_width    - window_width    - RIGHT_MARGIN)y = TOP_MARGINroot.geometry(    f"+{x}+{y}")# =========================================================# ARRONDI - DÉSACTIVÉ# ========================================================="""def make_rounded(hwnd, width, height, radius=10):    import ctypes    user32 = ctypes.windll.user32    gdi32 = ctypes.windll.gdi32    region = gdi32.CreateRoundRectRgn(        0,        0,        width,        height,        radius * 2,        radius * 2    )    user32.SetWindowRgn(        hwnd,        region,        True    )root.update_idletasks()make_rounded(    root.winfo_id(),    root.winfo_width(),    root.winfo_height(),    10)"""# =========================================================# DÉMARRAGE# =========================================================update()root.mainloop()